package com.internalops.workbench;
import com.internalops.api.ApiResponse;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/procurement") public class ProcurementController{private final ProcurementWorkflowService s;public ProcurementController(ProcurementWorkflowService s){this.s=s;}@PostMapping("/generate")public ApiResponse<Map<String,Object>> generate(){return ApiResponse.ok(s.generate());}@PostMapping("/suggestions/{id}/confirm")public ApiResponse<Map<String,Object>> confirm(@PathVariable long id){return ApiResponse.ok(s.confirm(id));}@PostMapping("/manual")public ApiResponse<Map<String,Object>> manual(@RequestBody ManualPurchaseRequest r){return ApiResponse.ok(s.manual(r));}@PostMapping("/purchases/{id}/payment")public ApiResponse<Map<String,Object>> pay(@PathVariable long id,@RequestBody FinanceActionRequest r){return ApiResponse.ok(s.payment(id,r));}@PostMapping("/purchases/by-number/{purchaseNo}/payment")public ApiResponse<Map<String,Object>> payByNumber(@PathVariable String purchaseNo,@RequestBody FinanceActionRequest r){return ApiResponse.ok(s.paymentByPurchaseNo(purchaseNo,r));}@PostMapping("/purchases/{id}/receive")public ApiResponse<Map<String,Object>> receive(@PathVariable long id){return ApiResponse.ok(s.receive(id));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<ApiResponse<Object>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(new ApiResponse<>(false,null,e.getMessage()));}@ExceptionHandler(IllegalStateException.class)ResponseEntity<ApiResponse<Object>> conflict(IllegalStateException e){return ResponseEntity.status(409).body(new ApiResponse<>(false,null,e.getMessage()));}}
